/** WKS-REG-MSG (534) = WKS-HDR-MSG (36) + WKS-MSG-TEXTO (498). */
public record MensajeS702(EncabezadoComs hdr, Aca aca, Sa0 sa0, EncabezadoSa2 sa2,
                          String areaUsuario /* X(409) */) {

    public record EncabezadoComs(char prefijo, char aplDest, int ccrDest, int lsnOrgn,
                                 String station,     // REDEFINES: tipo + sucursal + priv + caja
                                 int ccrOrgn, int copOrgn, String facultad, char aplOrig,
                                 int resultado,      // WKS-HDR-RSLTDO: 31-33 = error de respuesta
                                 String mascara, String password) {}

    public record Aca(int destino, int origen) {}     // 9(06) + 9(06)

    public record Sa0(int dSis, int dCod, int dSubCod,  // WKS-SA0-TRN-DEST 9(09) = 4 + 2 + 3
                      int oSis, int oCod, int oSubCod,  // WKS-SA0-TRN-ORIG
                      Direccion direccion, int longitud, int tiempoEspera, int respuesta) {

        public boolean paraS151() { return dSis == 151; }   // W88-SA0-TRN-DSIS-S151
    }

    /** WKS-SA0-DIRECCION y sus niveles 88. El valor se guarda tal cual como estatus del registro. */
    public enum Direccion {
        ALTA(1), RESPUESTA(2), BAJA(3), RESPUESTA_BAJA(4);
        public final int valor;
        Direccion(int v) { valor = v; }
        public static Direccion of(int v) {
            return Arrays.stream(values()).filter(d -> d.valor == v).findFirst()
                    .orElseThrow(() -> new MensajeInvalidoException("Dirección " + v));
        }
    }
}

/** WKS-AREA-MSG-OBL-SERV1. Vista usada por los subcódigos 1 y 3. */
public record RespuestaServ1(
        String contrato,          // 9(16): String para conservar ceros
        int cveMda,
        int mdaSuc,
        String mdaCta,            // 9(16)
        long autoriza,
        String refnum,            // 9(12)
        long autS151,             // 9(08)
        LocalDate fecMov,         // 9(06) AAMMDD, pivote 2000
        int cveTran,
        int ocurrencia,           // 9(02): 1..5, el importe dentro del movimiento S500
        BigDecimal importe,       // 9(14)V99 DISPLAY: escala 2
        int error) {              // 9(04): se graba en B07/B10-NUM-ERROR

    static RespuestaServ1 parse(String a) {
        return new RespuestaServ1(a.substring(0, 16), Fixed.entero(a, 16, 4), Fixed.entero(a, 20, 4),
                a.substring(24, 40), Fixed.largo(a, 40, 8), a.substring(48, 60), Fixed.largo(a, 60, 8),
                Fixed.fechaAammdd(a, 68), Fixed.entero(a, 74, 4), Fixed.entero(a, 78, 2),
                Fixed.decimal(a, 80, 16, 2), Fixed.entero(a, 96, 4));
    }
}

@Configuration
@RequiredArgsConstructor
public class ReceptorS702Config {

    /** 000000-PROCESO-GLOBAL: INICIO, PROCESO UNTIL W77-FIN = 1, CIERRA-BD, STOP RUN. */
    @Bean
    IntegrationFlow receptorS702(ComsInboundAdapter coms, RespuestaS702Router router) {
        return IntegrationFlow.from(coms)                 // 200600-COMS-RECEIVE
                .filter(MensajeS702.class, m -> m.sa0().paraS151(),
                        f -> f.discardChannel("descartados"))      // EXIT PERFORM si no es S151
                .route(router)                             // subcódigo 1, 2 o 3
                .get();
    }

    /** 700100-ABRE-BD UNTIL W77-FIN = 0 OR W77-INTENTO > 6, con WAIT(10) entre intentos. */
    @Bean
    RetryTemplate aperturaBifin() {
        return RetryTemplate.builder()
                .maxAttempts(7)                            // el contador empieza en 0 y corta en > 6
                .fixedBackoff(Duration.ofSeconds(10))
                .build();
    }
}

@Component
@RequiredArgsConstructor
public class ComsInboundAdapter extends MessageProducerSupport {

    private final ComsClient coms;                   // ESPERACOMS / RECEIVE COMS-IN
    private final DiaOperativo dia;                  // 202000-VALIDA-FEC-ACTUAL

    @Override
    protected void doStart() {
        Thread.ofVirtual().name("p017-coms").start(() -> {
            while (isRunning()) {
                EventoComs ev = coms.espera(Duration.ofSeconds(30));
                switch (ev.tipo()) {
                    case MENSAJE -> recibe();
                    case TIMEOUT -> dia.verificaCambioDeDia();     // rota display y monitor
                    case HI      -> { if (ev.hi() == 4 || ev.hi() == 6) stop(); }
                    default      -> log.warn("EVENTO DESCONOCIDO {}", ev.tipo());
                }
            }
        });
    }

    private void recibe() {
        RecepcionComs r = coms.receive();
        switch (r.statusKey()) {
            case 99 -> stop();                                  // FIN DE PROGRAMA X ESTATUS
            case 0, 89, 91, 92, 93 -> sendMessage(MessageBuilder.withPayload(r.mensaje()).build());
            default -> log.error(">> ERROR RECEIVE MSG >>> CS-COMS-IN-STATUS-KEY = {} {}",
                                 r.statusKey(), r.mensaje());
        }
    }
}

@Service
@RequiredArgsConstructor
public class RespuestaProtCobService {

    private final ProtCobRepository b07;       // S151B07PROTCOB
    private final DomiRepository b10;          // S151B10DOMI

    @ServiceActivator(inputChannel = "subcodigo")
    @Transactional
    public void aplica(MensajeS702 m) {
        Optional<? extends RegistroConEstatus> reg = switch (m.sa0().dSubCod()) {
            case 1 -> { var s = RespuestaServ1.parse(m.areaUsuario());
                        yield b07.porFecha(1, s.fecMov(), s.contrato(), s.autS151(), s.ocurrencia()); }
            case 2 -> { var s = RespuestaServ2.parse(m.areaUsuario());
                        yield b07.porCliente(2, s.fecCon(), s.custId(), s.accNum(),
                                             m.sa2().autS151(), m.sa2().ocurrencia()); }
            case 3 -> { var s = RespuestaServ1.parse(m.areaUsuario());     // contrato no forma parte de la llave
                        yield b10.porFechaAut(3, s.fecMov(), s.autS151(), s.ocurrencia()); }
            default -> Optional.empty();       // MOVE 1 TO WKS-EOF-B07: se ignora
        };
        reg.ifPresentOrElse(r -> transiciona(r, m), () -> log.warn("MSG RECIBIDO REG NO LOCALIZADO {}", m));
    }

    /** Solo dos transiciones válidas: 1 a 2 (respuesta de alta) y 3 a 4 (respuesta de baja). */
    private void transiciona(RegistroConEstatus r, MensajeS702 m) {
        var dir = m.sa0().direccion();
        boolean valida = (dir == Direccion.RESPUESTA && r.getStatus() == 1)
                      || (dir == Direccion.RESPUESTA_BAJA && r.getStatus() == 3);
        if (!valida) {
            log.warn("MSG RECIBIDO CON DIRECCION ERRONEA {} dir={} status={}", r.llave(), dir, r.getStatus());
            return;
        }
        r.setStatus(dir.valor);                // MOVE WKS-SA0-DIRECCION TO B07-STATUS
        r.setNumError(RespuestaServ1.parse(m.areaUsuario()).error());
    }
}

public interface ProtCobRepository extends JpaRepository<ProtCob, ProtCobId> {

    /** LOCK FIRST B07SXFECHA AT NUM-ID, FEC-CARGO, CONTRATO, AUT-S151, NUM-OCURR. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @QueryHints(@QueryHint(name = "jakarta.persistence.lock.timeout", value = "5000"))
    @Query("""
           select p from ProtCob p
            where p.numId = :numId and p.fecCargo = :fec and p.contrato = :contrato
              and p.autS151 = :aut and p.numOcurr = :occ
            order by p.id""")
    List<ProtCob> buscaPorFecha(int numId, LocalDate fec, String contrato, long aut, int occ, Pageable primero);

    default Optional<ProtCob> porFecha(int numId, LocalDate fec, String contrato, long aut, int occ) {
        return buscaPorFecha(numId, fec, contrato, aut, occ, PageRequest.of(0, 1)).stream().findFirst();
    }
}

