@Entity
@Table(name = "s151_b07_protcob")
public class ProtCob implements RegistroConEstatus {

    @EmbeddedId private ProtCobId id;
    private int status;            // B07-STATUS
    private int numError;          // B07-NUM-ERROR
    @Version private long version;

    // 030203-ACTUALIZA-B07-RES: setStatus(dir) + setNumError(err). El STORE lo hace el commit
    // de la transacción de RespuestaProtCobService.aplica (BEGIN/END-TRANSACTION).
}

@ControllerAdvice
class ErroresPersistencia {
    /**
     * 700200-ALMACENA-REG: DEADLOCK hace FREE y sigue (se pierde la actualización);
     * DUPLICATES solo se informa; cualquier otro error termina el programa.
     * En Java el deadlock revierte y el mensaje se reintenta; el resto se conserva.
     */
    @ExceptionHandler(DataIntegrityViolationException.class)
    void duplicado(DataIntegrityViolationException e) { log.warn("REG DUPLICADO {}", e.getMessage()); }
}

@Entity
