public class Domi implements RegistroConEstatus {

    @EmbeddedId private DomiId id;   // NUM-ID 3, FEC-CARGO, AUT-S151, NUM-OCURR (el contrato quedó fuera de la llave)
    private int status;              // B10-STATUS: 0 pendiente, 1 enviado, 2 respondido, 3 cancelado,
                                     //             4 baja respondida, 5 cancelación pendiente, 6 anulado
    private int numError;
    @Version private long version;
}

public interface DomiRepository extends JpaRepository<Domi, DomiId> {

    /** LOCK FIRST B10SXFECAUT151; la condición por contrato está comentada en la línea 1912. */
